/**
 * @file sticker-art.data.ts
 * @description The owner's sticker artwork for the printable QR sheet
 * (HOS-2688), as a 1254x1254 baseline JPEG embedded as base64.
 *
 * Embedded in a module rather than read from disk at runtime: the API ships as
 * one tsup bundle (`dist/index.js`) and `pnpm deploy` copies no loose asset
 * files into the image, so a `readFileSync` next to this file would work in dev
 * and fail in production. Same pattern as `lib/brand-icon/icon-png.data.ts`.
 *
 * ## It is a CLEANED copy of the owner's file
 *
 * The owner's original (`calcos/12.jpeg`, 1254x1254) carries a SAMPLE QR in
 * its white box and the copy «ESCANEÁ PARA / CONOCER ESTE LUGAR» in its blue
 * pill. Both are painted out here so the renderer can draw the real code and
 * the listing's own name on clean ground:
 *
 * - rectangle (668,538)-(1104,974), filled with the box's white `#FEFEFE`;
 * - rectangle (598,1015)-(1164,1124), filled with the pill's blue `#0150B7`
 *   (sampled from the pill's flat interior).
 *
 * Both rectangles sit inside the rounded corners of their shapes, so the
 * rounded outlines are the artwork's own. Re-encoded at quality 90, 4:4:4.
 *
 * To regenerate (e.g. when the owner sends the higher-resolution version):
 * paint the same two regions, SCALED to the new side, then
 * `base64 -w0 <file>.jpg`. The renderer's geometry is expressed in the
 * artwork's 1254-unit space and scales with the drawn size, not with the
 * file's pixel count, so a sharper file of the same art needs no other change.
 */

/** Side of the artwork's coordinate space. Every geometry constant is in these units. */
export const STICKER_ART_UNITS = 1254;

/** Base64 of the cleaned sticker artwork JPEG. */
export const STICKER_ART_JPEG_BASE64 =
    '';
